{\"n\":12,\"src\":\"MAJAZ\",\"g\":\"core\",\"c\":[\"16d\"],\"why\":\"Poetic example supports the generic singular followed by exception construction.\"}
{\"n\":13,\"src\":\"ABDURRAZZAQ\",\"g\":\"core\",\"c\":[\"16d\",\"19d\"],\"why\":\"Reports the broad loss judgment and specifies the four conditions for its exception.\"}
