{\"n\":20,\"src\":\"TAB-FULL\",\"g\":\"core\",\"c\":[\"1d\",\"6d\"],\"why\":\"Variant reading extends the loss judgment to time's end, qualifying its temporal scope.\"}
{\"n\":21,\"src\":\"TAB-FULL\",\"g\":\"core\",\"c\":[\"16d\",\"19d\"],\"why\":\"Identifies believers as those excepted from the general loss judgment.\"}
