{\"n\":31,\"src\":\"THALABI\",\"g\":\"core\",\"c\":[\"16d\",\"19d\"],\"why\":\"Affirms that those meeting the exception's conditions are not in loss.\"}
{\"n\":32,\"src\":\"THALABI\",\"g\":\"core\",\"c\":[\"1c\",\"1d\",\"2c\",\"2d\",\"16d\"],\"why\":\"Reports a day-end oath, identifies Abū Jahl in loss, and maps the exception to companions.\"}
{\"n\":33,\"src\":\"THALABI\",\"g\":\"core\",\"c\":[\"1c\",\"1d\",\"2c\",\"2d\",\"16d\"],\"why\":\"Repeats the day-end oath, Abū Jahl referent, and named identities for the exception.\"}
{\"n\":34,\"src\":\"MAWARDI-FULL\",\"g\":\"core\",\"c\":[\"1d\",\"10b\",\"22c\"],\"why\":\"Offers punishment as a meaning of khusr, qualifying the page's account of loss.\"}
{\"n\":35,\"src\":\"MAWARDI-FULL\",\"g\":\"core\",\"c\":[\"1d\",\"2c\",\"2d\",\"6d\"],\"why\":\"Expanded reading links al-ʿaṣr to time's vicissitudes and makes loss last through time.\"}
{\"n\":36,\"src\":\"MAWARDI-FULL\",\"g\":\"core\",\"c\":[\"1d\",\"16d\"],\"why\":\"Identifies al-insān as humankind as a whole in the general loss judgment.\"}
{\"n\":37,\"src\":\"MAWARDI-FULL\",\"g\":\"core\",\"c\":[\"1d\",\"10b\",\"22c\"],\"why\":\"Reports ruin as one meaning of khusr, an alternative to the page's loss image.\"}
{\"n\":38,\"src\":\"MAWARDI-FULL\",\"g\":\"core\",\"c\":[\"1d\",\"10b\",\"22c\"],\"why\":\"Reports evil as a meaning of khusr, qualifying the page's account of loss.\"}
{\"n\":39,\"src\":\"MAWARDI-FULL\",\"g\":\"core\",\"c\":[\"1d\",\"10b\",\"22c\"],\"why\":\"Reports decrease as a meaning of khusr, an alternative loss account.\"}
{\"n\":40,\"src\":\"QUSHAYRI\",\"g\":\"core\",\"c\":[\"1d\",\"6d\",\"10b\",\"22c\"],\"why\":\"Distinguishes loss in deeds at the outcome from loss in spiritual states now.\"}
{\"n\":41,\"src\":\"QUSHAYRI\",\"g\":\"core\",\"c\":[\"1d\",\"6d\",\"10b\"],\"why\":\"Defines present spiritual loss as contraction after expansion and veiling after nearness.\"}
{\"n\":42,\"src\":\"QUSHAYRI\",\"g\":\"core\",\"c\":[\"1d\",\"6d\",\"10b\"],\"why\":\"Adds returning to dispensations as a form of spiritual loss in the present state.\"}
{\"n\":43,\"src\":\"QUSHAYRI\",\"g\":\"core\",\"c\":[\"1d\",\"10b\",\"16d\",\"22c\"],\"why\":\"Reads al-insān as the human species and khusr as perdition, defining judgment and scope.\"}
{\"n\":44,\"src\":\"QUSHAYRI\",\"g\":\"core\",\"c\":[\"1d\",\"10b\",\"22c\"],\"why\":\"Reads khusr as punishment for sins, a rival account of the page's loss image.\"}
{\"n\":45,\"src\":\"WAHIDI-BASIT\",\"g\":\"core\",\"c\":[\"1d\",\"16d\"],\"why\":\"Reports al-insān as a generic noun for all people in the broad judgment.\"}
{\"n\":46,\"src\":\"WAHIDI-BASIT\",\"g\":\"core\",\"c\":[\"1d\",\"10b\",\"22c\"],\"why\":\"Defines khusr as deficiency and loss of capital, qualifying the page's loss image.\"}
EOF"

